  dispatchMessage({ command: 'projectsLoaded', projects: { projects: [], selectedProjectPath: '', portfolio: [] } });
  assert.equal(postedMessages.some(message => message.command === 'sidebarInitialDataReady'), false);
  frames.shift()();
