test('sidebar keeps solo composer active and renders pasted attachments while the input stays focused', async () => {
  const { SolopreneurSidebarProvider } = loadCompiledModule(
    'out/sidebarProvider.js',
    ''
  );
  const provider = new SolopreneurSidebarProvider(
    createUri(projectRoot),
    { getNodes: () => [] },
    async () => {},
    () => ({ cliPath: 'codex', language: 'zh', globalPrompt: '', globalDataPath: '/workspace/.solomap-global' }),
    async () => {},
    () => ({ projects: [], selectedProjectPath: '' }),
    async () => {},
    async () => {}
  );
  const webviewView = {
    webview: {
      options: {},
      html: '',
      asWebviewUri(uri) {
        return String(uri && (uri.fsPath || uri.path || uri));
      },
      postMessage() {
        return Promise.resolve(true);
      },
      onDidReceiveMessage() {}
    }
  };
  provider.resolveWebviewView(webviewView, {}, {});
  const script = extractLastScript(webviewView.webview.html);
  const suffix = `
    window.__soloModeAfterNodesLoaded = (() => {
      const projectPath = '/workspace/app';
      const project = { name: 'app', path: projectPath, nodes: [] };
      currentSettings = { cliPath: 'codex', language: 'zh' };
      currentProjects.selectedProjectPath = projectPath;
      currentProjects.portfolio = [project];
      activeProjectPath = projectPath;
      currentNodes = [];
      const beforeNodes = renderProjectConversationComposer(project, currentNodes);
      const input = {
        value: '正在输入 Solo 草稿',
        getAttribute(name) {
          if (name === 'data-conversation-mode') return 'solo';
          if (name === 'data-project-path') return projectPath;
          if (name === 'data-conversation-target-id') return 'solo:' + projectPath;
          return '';
        }
      };
      rememberProjectConversationInput(input);
      const rememberedDraftBeforePaste = projectSoloDrafts[projectPath];
      currentNodes = [{ id: '1', title: '下一步', status: 'Pending', dependencies: '', agentCli: 'codex' }];
      const afterNodes = renderProjectConversationComposer(project, currentNodes);
      projectConversationModes[projectPath] = 'continue';
      portfolioList.querySelector = selector => selector === '[data-project-conversation-input]' ? input : null;
      captureProjectConversationInputState();
      const continueMode = renderProjectConversationComposer(project, currentNodes);
      projectConversationModes[projectPath] = 'flow';
      captureProjectConversationInputState();
      const flowMode = renderProjectConversationComposer(project, currentNodes);
      projectConversationModes[projectPath] = 'solo';
      const focusedInput = document.createElement('focused-project-input');
      focusedInput.value = '粘贴前仍在输入';
      focusedInput.setAttribute('data-conversation-mode', 'solo');
      focusedInput.setAttribute('data-project-path', projectPath);
      focusedInput.setAttribute('data-conversation-target-id', 'solo:' + projectPath);
      focusedInput.closest = selector => selector === '[data-project-continue-composer]' ? {} : null;
      window.__pendingPasteReaders = [];
      window.__delayPasteReader = false;
      globalThis.FileReader = class {
        readAsDataURL() {
          if (window.__delayPasteReader) {
            window.__pendingPasteReaders.push(this);
            return;
          }
          this.result = 'data:image/png;base64,aGVsbG8=';
          this.onload();
        }
      };
      document.activeElement = focusedInput;
      portfolioList.innerHTML = 'before-paste';
      portfolioList.querySelector = selector => selector === '[data-project-conversation-input]' ? focusedInput : null;
      bindPastedImageAttachments(focusedInput, 'solo:' + projectPath, () => projectPath, 'solo:' + projectPath);
      const pasteImage = () => focusedInput.listeners.paste({
        clipboardData: {
          items: [{
            kind: 'file',
            type: 'image/png',
            getAsFile: () => ({ name: 'screenshot.png', type: 'image/png' })
          }]
        },
        preventDefault() {}
      });
      pasteImage();
      window.__pasteAnotherSoloImage = () => {
        window.__delayPasteReader = true;
        pasteImage();
      };
      window.__releasePasteReader = () => {
        const reader = window.__pendingPasteReaders.shift();
        reader.result = 'data:image/png;base64,bGF0ZQ==';
        reader.onload();
      };
      window.__sendSoloComposer = () => {
        const sendInput = document.createElement('send-input');
        sendInput.value = '发送当前消息';
        const sendButton = document.createElement('send-button');
        sendButton.setAttribute('data-conversation-mode', 'solo');
        sendButton.setAttribute('data-project-path', projectPath);
        sendButton.setAttribute('data-conversation-target-id', 'solo:' + projectPath);
        const panel = {
          querySelector(selector) {
            if (selector === '[data-project-conversation-input]') return sendInput;
            return null;
          }
        };
        sendButton.closest = selector => selector === '[data-project-continue-composer]' ? panel : null;
        const container = {
          querySelector() { return null; },
          querySelectorAll(selector) {
            return selector === '[data-project-continue-send]' ? [sendButton] : [];
          }
        };
        bindProjectContinueComposer(container);
        sendButton.listeners.click({ stopPropagation() {} });
      };
      return {
        beforeWasSolo: /data-conversation-mode="solo"/.test(beforeNodes),
        rememberedMode: 'solo',
        rememberedDraft: rememberedDraftBeforePaste,
        afterStillSolo: /data-conversation-mode="solo"/.test(afterNodes),
        afterSoloButtonActive: /portfolio-mode-btn active" data-project-conversation-mode="solo"/.test(afterNodes),
        afterContinueInput: /data-conversation-mode="continue"/.test(afterNodes),
        continueButtonActive: /portfolio-mode-btn active" data-project-conversation-mode="continue"[^>]*aria-pressed="true"/.test(continueMode),
        flowButtonActive: /portfolio-mode-btn active" data-project-conversation-mode="flow"[^>]*aria-pressed="true"/.test(flowMode),
        flowButtonEnabled: !/data-project-conversation-mode="flow"[^>]*disabled/.test(flowMode),
        pastedImagePendingRendered: /正在添加截图/.test(portfolioList.innerHTML)
      };
    })();
  `;
  const { context, elements, postedMessages, dispatchMessage } = runScriptWithMinimalDom(script, [
    'tasks-list',
    'progress-bar',
    'progress-text',
    'btn-open-strategy-pyramid',
    'project-select',
    'btn-add-project',
    'global-focus-panel',
    'portfolio-title',
    'portfolio-list',
    'portfolio-filters',
    'btn-toggle-intelligence',
    'btn-close-intelligence',
    'btn-intelligence-back',
    'btn-intelligence-new',
    'intelligence-panel',
    'intelligence-home',
    'intelligence-thread',
    'intelligence-recent',
    'intelligence-input',
    'intelligence-send',
    'intelligence-error',
    'feedback-panel',
    'feedback-title',
    'feedback-type-not-working',
    'feedback-type-next-step',
    'feedback-type-feature',
    'btn-toggle-settings',
    'btn-close-settings',
    'settings-panel',
    'setting-language',
    'setting-cli-select',
    'setting-clipath-custom',
    'setting-global-prompt',
    'setting-global-data-path',
    'pro-account-panel',
    'btn-open-pro-authorization',
    'btn-account-logout',
    'setting-feedback-title',
    'setting-feedback-body',
    'btn-open-feedback',
    'btn-test-cli',
    'btn-save-settings',
    'btn-check-dependencies',
    'btn-open-agent-install',
    'btn-prepare-agent-automation',
    'btn-open-agent-check',
    'btn-open-github-auth',
    'dependency-agent-status',
    'dependency-agent-message',
    'dependency-automation-status',
    'dependency-automation-message',
    'dependency-github-status',
    'dependency-github-message',
    'cli-test-badge'
  ], suffix);

  const result = context.window.__soloModeAfterNodesLoaded;
  assert.equal(result.beforeWasSolo, true);
  assert.equal(result.rememberedMode, 'solo');
  assert.equal(result.rememberedDraft, '正在输入 Solo 草稿');
  assert.equal(result.afterStillSolo, true);
  assert.equal(result.afterSoloButtonActive, true);
  assert.equal(result.afterContinueInput, false);
  assert.equal(result.continueButtonActive, true);
  assert.equal(result.flowButtonActive, true);
  assert.equal(result.flowButtonEnabled, true);
  assert.equal(result.pastedImagePendingRendered, true);

  await new Promise(resolve => setImmediate(resolve));
  const saveMessage = postedMessages.find(message => message.command === 'attachment.save');
  assert.ok(saveMessage);

  dispatchMessage({
    command: 'pastedAttachmentsSaved',
    targetId: 'solo:/workspace/app',
    requestId: saveMessage.requestId,
    files: ['.solopreneur/attachments/solo-workspace-app/screenshot.png']
  });
  assert.match(elements['portfolio-list'].innerHTML, /screenshot\.png/);
  assert.doesNotMatch(elements['portfolio-list'].innerHTML, /正在添加截图/);

  context.window.__pasteAnotherSoloImage();
  context.window.__sendSoloComposer();
  assert.ok(postedMessages.some(message => message.command === 'conversation.runSolo'));
  context.window.__releasePasteReader();
  await new Promise(resolve => setImmediate(resolve));
  const lateSaveMessage = postedMessages.filter(message => message.command === 'attachment.save').at(-1);
  dispatchMessage({
    command: 'pastedAttachmentsSaved',
    targetId: 'solo:/workspace/app',
    requestId: lateSaveMessage.requestId,
    attachmentEpoch: lateSaveMessage.attachmentEpoch,
    files: ['.solopreneur/attachments/solo-workspace-app/late-screenshot.png']
  });
  assert.doesNotMatch(elements['portfolio-list'].innerHTML, /late-screenshot\.png/, 'an attachment reply from before send must not repopulate the composer');
});

