  for (const [index, name] of ['step-1.json', 'solo-1.json'].entries()) store.upsertProjectRunIndex(projectIds.get(projectRootA), { ...JSON.parse(fs.readFileSync(path.join(digestRoot, name), 'utf8')), executionLogId: index + 1 });
