test('strategy pyramid snapshot sends portfolio facts through the intelligent kernel and writes its judgment', async t => {
  const extensionModule = loadCompiledModule(
    'out/extension.js',
    'module.exports.__buildStrategyPyramidSnapshot = buildStrategyPyramidSnapshot;'
  );
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'solopreneur-strategy-pyramid-'));
  const globalRoot = path.join(root, '.solomap-global');
  const coreProject = path.join(root, 'solomap');
  const contentProject = path.join(root, 'content');
  fs.mkdirSync(path.join(coreProject, '.solopreneur'), { recursive: true });
  fs.mkdirSync(path.join(contentProject, '.solopreneur'), { recursive: true });
  fs.writeFileSync(path.join(coreProject, '.solopreneur', 'roadmap.csv'), [
    'id,title,description,stage,dependencies,agentCli,agentPrompt,status,createdAt,completedAt',
    '1,Build Pro cockpit,,产品与 MVP,,,,Completed,,',
    '2,Sell Pro subscription,,销售与增长,,,,In Progress,,',
    '3,Learn from paid users,,反馈与学习,,,,Pending,,',
    '4,Improve onboarding,,改进与规模化,,,,Pending,,'
  ].join('\n'), 'utf8');
  fs.writeFileSync(path.join(contentProject, '.solopreneur', 'roadmap.csv'), [
    'id,title,description,stage,dependencies,agentCli,agentPrompt,status,createdAt,completedAt',
    '1,Publish SEO content,,销售与增长,,,,Pending,,'
  ].join('\n'), 'utf8');
  fs.mkdirSync(globalRoot, { recursive: true });
  fs.writeFileSync(path.join(globalRoot, 'projects.json'), JSON.stringify({
    schemaVersion: 1,
    updatedAt: '2026-06-06T00:00:00.000Z',
    hiddenProjects: [],
    projects: [
      { name: 'SoloMap', path: coreProject, type: 'core_product' },
      { name: 'Content Engine', path: contentProject, type: 'content' }
    ]
  }, null, 2), 'utf8');
  const native = await require('./analysis-fixture.js').openAnalysisOwner(t, globalRoot, [{ name: 'SoloMap', path: coreProject }, { name: 'Content Engine', path: contentProject }]);
  await require('../out/projectRegistry.js').refreshProjectRegistry(globalRoot, () => ({
    legacyProjects: [{ name: 'SoloMap', path: coreProject, type: 'core_product' }, { name: 'Content Engine', path: contentProject, type: 'content' }]
  }), (operation, input) => native.ops({ operation, input }));
  const scope = native.projectIds.get(coreProject);
  const evidence = native.store.write({ kind: 'evidence', action: 'create', scope, idempotencyKey: 'strategy-kernel-evidence', data: { type: 'host_observation', source_actor_id: 'local-runtime', content: 'node --test checkout-flow.test.js passed', observed_at: Date.now() } });
  native.store.write({ kind: 'learning_event', action: 'create', scope, idempotencyKey: 'strategy-kernel-event', data: { source_object_id: evidence.objectId, source_revision: 1, event_type: 'verified', source_type: 'flow_loop', summary: 'Verifier closed the checkout flow after running the final UI test.', verification_signal: 1, occurred_at: Date.now() } });

  const context = {
    globalState: {
      get(key) {
        if (key === 'solopreneur.settings') {
          return { cliPath: 'agy', language: 'zh', globalPrompt: '', globalDataPath: globalRoot };
        }
        return undefined;
      },
      update() {
        return Promise.resolve();
      }
    }
  };

  const snapshot = await extensionModule.__buildStrategyPyramidSnapshot(context, {
    id: 'pi-agent:agent-cli:agy:gpt-test:strategy-test',
    async judgeStrategyPyramid(input) {
      return {
        confidence: 'medium',
        stageTitle: '商业验证期',
        mainJudgment: `当前 ${input.totals.projects} 个项目需要补齐商业验证。`,
        strategicAction: '集中核心产品的销售与反馈验证。',
        constraint: '验证完成前不新增产品线。',
        risks: ['商业化证据不足。'],
        moves: [
          { horizon: '未来 30 天', title: '验证核心产品转化', reason: '建设信号已经充足。', evidence: ['SoloMap 路线图包含销售环节'] },
          { horizon: '本季度', title: '按验证结果收缩组合', reason: '先形成收入证据再分配投入。', evidence: ['当前有 2 个项目'] }
        ],
        recommendedScenarioPath: '推荐路径：先验证核心产品收入，再决定是否扩展组合。',
        projects: input.projects.map(project => ({
          id: project.id,
          action: '推进真实市场验证',
          risk: '收入证据不足',
          advice: { doubleDown: '销售与反馈', reduce: '新增功能', observe: '真实转化' }
        }))
      };
    }
  });
  const snapshotPath = path.join(globalRoot, 'strategy', 'pyramid-snapshot.json');
  const projectStrategyPath = path.join(globalRoot, 'strategy', 'project-strategy.csv');
  const abilityRegistryPath = path.join(globalRoot, 'strategy', 'ability-registry.csv');
  assert.equal(snapshot.totalProjects, 2);
  assert.equal(snapshot.decisionSource, 'cognitive');
  assert.equal(snapshot.engineStatus, 'completed');
  assert.equal(snapshot.mainJudgment, '当前 2 个项目需要补齐商业验证。');
  assert.equal(snapshot.stageTitle.length > 0, true);
  assert.equal(snapshot.stageProfile.defaultQuestion.length > 0, true);
  assert.match(snapshot.mainJudgment, /组合|项目|Build|收入|反馈|核心/);
  assert.match(snapshot.strategicAction, /商业化|核心产品|销售|反馈|收入/);
  assert.equal(snapshot.layers.length, 5);
  assert.equal(snapshot.structureSignals.length, 5);
  assert.ok(snapshot.structureSignals.some((signal) => signal.key === 'learning'));
  assert.ok(snapshot.riskSignals.length >= 1);
  assert.ok(snapshot.opportunitySignals.length >= 1);
  assert.ok(snapshot.opportunitySignals.some((signal) => /学习复利机会/.test(signal.title)));
  assert.ok(snapshot.learningSignals.some((signal) => signal.projectName === 'app' || signal.projectPath === coreProject));
  assert.equal(snapshot.scenarios.length, 3);
  assert.match(snapshot.recommendedScenarioPath, /推荐路径/);
  assert.ok(snapshot.loops.some((loop) => loop.key === 'sell' && loop.count >= 1));
  assert.ok(snapshot.moves.length >= 2);
  assert.ok(snapshot.projects.some((project) => project.name === 'SoloMap' && project.role === '核心产品' && project.roleScores.brandValue >= 1));
  assert.equal(fs.existsSync(snapshotPath), false);
  assert.equal(fs.existsSync(projectStrategyPath), false);
  assert.equal(fs.existsSync(abilityRegistryPath), false);
  const written = native.store.readStrategyState(null).value.snapshot;
  assert.equal(written.totalProjects, 2);
  assert.equal(written.layers.length, 5);

  const fallback = await extensionModule.__buildStrategyPyramidSnapshot(context, {
    id: 'pi-agent:agent-cli:agy:gpt-test:strategy-failure',
    async judgeStrategyPyramid() {
      throw new Error('model pipe unavailable');
    }
  });
  assert.equal(fallback.decisionSource, 'rules_fallback');
  assert.equal(fallback.engineStatus, 'failed');
  assert.equal(fallback.totalProjects, 2);
  const failedState = native.store.readStrategyState(null).value;
  assert.equal(failedState.engineConfigRevision, 'strategy-failure');
  assert.equal(failedState.snapshot.engineStatus, 'failed');
  const derived = native.store.readStrategyState(null).value.derivedRegistries;
  assert.ok(derived.projects.some(project => project.projectPath === coreProject));
  assert.ok(derived.abilities.length > 0);
  assert.equal(fs.existsSync(projectStrategyPath), false);
  assert.equal(fs.existsSync(abilityRegistryPath), false);

  const judgment = mainJudgment => ({ confidence: 'medium', stageTitle: '验证期', mainJudgment, strategicAction: '验证', constraint: '不扩张', risks: [], moves: [], recommendedScenarioPath: '验证', projects: [] });
  let finishOld; let entered;
  const result = new Promise(resolve => { finishOld = resolve; });
  const started = new Promise(resolve => { entered = resolve; });
  const older = extensionModule.__buildStrategyPyramidSnapshot(context, { id: 'test-engine:same-model', async judgeStrategyPyramid() { entered(); return result; } });
  await started;
  await extensionModule.__buildStrategyPyramidSnapshot(context, { id: 'test-engine:same-model', async judgeStrategyPyramid() { return judgment('较新的判断'); } });
  finishOld(judgment('迟到的判断'));
  assert.equal((await older).mainJudgment, '较新的判断');
  assert.equal(native.store.readStrategyState(null).value.snapshot.mainJudgment, '较新的判断');
});

test('strategy local access uses a valid retained grant while remote verification is pending', async () => {
  let release;
  const remote = new Promise(resolve => { release = resolve; });
  // The compiled module runs in its own VM; replace only the remote verification boundary.
  const subject = loadCompiledModule('out/extension.js', 'module.exports.localAccess = hasLocalStrategyPyramidAccess;', {
    './proAccount': { ...require('../out/proAccount.js'), verifyPassportGrant: () => remote }
  });
  const expiry = '2999-01-01T00:00:00.000Z';
  const context = { secrets: { get: async () => JSON.stringify({ grant: 'retained-grant', email: 'fixture@example.invalid', userId: 'fixture-user', entitlements: ['strategy_pyramid'], expiresAt: expiry, checkedAt: new Date().toISOString() }) }, globalState: { get: key => key === 'solopreneur.settings' ? { globalDataPath: '/fixture', proEntitlements: { strategy_pyramid: true }, proAccount: { authenticated: true, allowed: true, expiresAt: expiry } } : undefined } };
  const access = subject.localAccess(context);
  try { assert.equal(await Promise.race([access, new Promise(resolve => setImmediate(() => resolve('still waiting')))]), true); }
  finally { release({ allowed: false, verificationUnavailable: true, reason: 'verify_failed' }); await access; }
});

