  const nodes = [{ id: 'custom', title: '用户标准', agentPrompt: '测试完整结果', stage: '实施', status: 'Pending' }, { id: 'missing', title: '新步骤', agentPrompt: '产出结果', stage: '实施', status: 'Pending' }];
